mapper.select:
select ib.id, ib.bin_id, ib.batch_id, ib.product_status, ib.total_qty,
       b.batch_no
from inventory_bin ib
inner join inventory_batch b on ib.batch_id = b.id
where b.sku_id = #{skuId}
  and b.warehouse_id = #{warehouseId}
  and ib.total_qty >= #{minQty}

mapper.update:
update inventory_bin
bin_id = #{binId}, batch_id = #{batchId}, product_status = #{productStatus}, total_qty = #{totalQty},
where id = #{id}
